// pages and legacySlugs are generated by scripts/build.mjs.
export default {
  async fetch(request, env) {
    if (!['GET', 'HEAD'].includes(request.method)) return new Response('Method not allowed', { status: 405, headers: { Allow: 'GET, HEAD' } })
    const url = new URL(request.url)
    const path = url.pathname.replace(/\/$/, '') || '/'
    const slug = path.startsWith('/modelos/') ? path.slice(9) : ''
    if (Object.hasOwn(legacySlugs, slug)) return Response.redirect(new URL(`/modelos/${legacySlugs[slug]}${url.search}`, url.origin), 308)
    // Use the platform request URL, never forwarded host headers or user input.
    const origin = url.origin.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char])
    if (path === '/robots.txt') return new Response(`User-agent: *\nAllow: /\nSitemap: ${url.origin}/sitemap.xml\n`, { headers: { 'Content-Type': 'text/plain; charset=utf-8' } })
    if (path === '/sitemap.xml') return new Response(`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${Object.keys(pages).filter(route => route !== '/404').map(route => `<url><loc>${origin}${route}</loc></url>`).join('')}</urlset>`, { headers: { 'Content-Type': 'application/xml; charset=utf-8' } })
    if (Object.hasOwn(pages, path)) return new Response(request.method === 'HEAD' ? null : pages[path].replaceAll('__SITE_ORIGIN__', origin), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'strict-origin-when-cross-origin' } })
    if (path.startsWith('/assets/') || path.startsWith('/images/') || ['/og.png', '/logo.jpg', '/favicon.svg'].includes(path)) return env.ASSETS.fetch(request)
    return new Response(request.method === 'HEAD' ? null : pages['/404'].replaceAll('__SITE_ORIGIN__', origin), { status: 404, headers: { 'Content-Type': 'text/html; charset=utf-8' } })
  },
}
